      const payload = { comm: { uin: Number(uin), format: 'json', ct: 24, cv: 0 }, req_0: { module: 'vkey.GetVkeyServer', method: 'CgiGetVkey', param: { filename: [file], guid, songmid: [id], songtype: [0], uin, loginflag: cookie ? 1 : 0, platform: '20' } } };
